ALTER DATABASE [{db}] ADD FILEGROUP MOD CONTAINS MEMORY_OPTIMIZED_DATA
GO
ALTER DATABASE [{db}] ADD FILE (NAME = '{db}_mod', FILENAME = '/var/opt/mssql/data/{db}_mod') TO FILEGROUP MOD
GO
CREATE TABLE dbo.Hot (Id int NOT NULL CONSTRAINT PK_Hot PRIMARY KEY NONCLUSTERED, Name nvarchar(50) NOT NULL) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_AND_DATA)
GO
CREATE TABLE dbo.Cold (Id int NOT NULL CONSTRAINT PK_Cold PRIMARY KEY, Name nvarchar(50) NOT NULL)
GO
INSERT dbo.Hot VALUES (1, N'a'), (2, N'b')
